// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address initiator, address from, uint256 tokenId, bytes calldata data) public {
        bytes4 expected = c.onERC721Received.selector;
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(expected, initiator, from, tokenId, data));
        assertTrue(ok && abi.decode(ret, (bytes4)) == expected);
    }
}
